  const tick = () => {
    const t = (Date.now() - t0) / 1000
    D.forEach((d, i) => {
      const p = pp(t - d.lag, d.spd, d.a, d.b, d.ph), dir = p[1]
      const x = Math.round(p[0] - (dir > 0 ? d.OX : d.W2 - d.OX)), y = Math.round(d.wl - d.WL + 0.9 * Math.sin(t * 1.4 + i))
